void obd_can_activate (void)
{    
#if DBG_OBD_CAN == 1
  dbg_tx_text("*** obd_can_activate()\r\n"); 
#endif

  // OBD CAN must be explicitly activated
  // a) at start
  // b) after deactivation because bus is disconnected
  // c) after deactivation because scantool is detected

  obd_can_vars.is_active = TRUE;
}

